    ModuleActivity(
      id: 'auditPlanningWorkshop',
      tab: ActivityTab.sim,
      kind: ActivityKind.caseScenario,
      title: Bi('Audit Planning Workshop', 'ورشة تخطيط التدقيق'),
      description: Bi('Lead an audit planning engagement step by step', 'قُد مهمة تخطيط التدقيق خطوة بخطوة'),
      maxScore: 100,
      instruction: Bi('Lead an audit planning engagement by assessing risks, setting materiality, allocating resources, and ensuring quality control.', 'قُد مهمة تخطيط التدقيق من خلال تقييم المخاطر وتحديد الأهمية النسبية وتخصيص الموارد وضمان مراقبة الجودة.'),
      scenarios: [
        CaseScenario(id: 'scenario1', title: Bi('Annual Financial Statement Audit', 'تدقيق القوائم المالية السنوية'), role: Bi('Audit Manager, External Audit Firm', 'مدير تدقيق، شركة تدقيق خارجية'), overview: Bi('You are the audit manager assigned to lead the annual financial statement audit of a mid-sized company. This is a recurring engagement with no prior year issues. You must plan the audit, assess risks, allocate resources, and ensure quality.', 'أنت مدير التدقيق المكلف بقيادة تدقيق القوائم المالية السنوية لشركة متوسطة الحجم. هذه مهمة متكررة بدون مشاكل من العام السابق. يجب عليك تخطيط التدقيق وتقييم المخاطر وتخصيص الموارد وضمان الجودة.'), finalSummary: Bi('You have successfully planned a financial audit by: identifying key risks (ERP implementation), setting appropriate materiality (1% of expenditure), allocating specialized resources (IT auditor), implementing quality controls (EQCR), and communicating with stakeholders.', 'نجحت في تخطيط تدقيق مالي من خلال: تحديد المخاطر الرئيسية (تطبيق ERP)، تحديد الأهمية النسبية المناسبة (1% من النفقات)، تخصيص موارد متخصصة (مدقق تكنولوجيا المعلومات)، تطبيق ضوابط الجودة (مراجعة مراقبة جودة المهمة)، والتواصل مع أصحاب المصلحة.'), steps: [
            CaseStep(id: 'step1', type: CaseStepType.analysis, title: Bi('Assess the Audit Environment', 'تقييم بيئة التدقيق'), description: Bi('Before detailed planning, you need to understand the current situation.', 'قبل التخطيط التفصيلي، تحتاج إلى فهم الوضع الحالي.'), data: [CaseDatum(Bi('Annual Expenditure', 'النفقات السنوية'), 'AED 500M'), CaseDatum(Bi('Prior Year Opinion', 'رأي العام السابق'), 'Unqualified'), CaseDatum(Bi('Staff Changes', 'تغييرات الموظفين'), 'New CFO (6 months)'), CaseDatum(Bi('System Changes', 'تغييرات النظام'), 'New ERP this year')], question: Bi('Which factor creates the highest audit risk for this engagement?', 'أي عامل يخلق أعلى مخاطر تدقيق لهذه المهمة؟'), options: [
                CaseOption(Bi('New ERP system implementation', 'تطبيق نظام ERP جديد'), isCorrect: true, feedback: Bi('Correct! New systems carry significant risk of data migration errors, control gaps, and user errors during transition.', 'صحيح! الأنظمة الجديدة تحمل مخاطر كبيرة من أخطاء نقل البيانات وثغرات الرقابة وأخطاء المستخدمين أثناء الانتقال.')),
                CaseOption(Bi('New CFO (6 months tenure)', 'مدير مالي جديد (6 أشهر في المنصب)'), feedback: Bi('While management changes matter, a new CFO with 6 months experience has had time to understand operations.', 'على الرغم من أهمية تغييرات الإدارة، فإن مديراً مالياً جديداً بخبرة 6 أشهر لديه وقت لفهم العمليات.')),
                CaseOption(Bi('Prior year unqualified opinion', 'رأي العام السابق غير متحفظ'), feedback: Bi('A clean prior year opinion actually reduces risk, not increases it.', 'رأي العام السابق النظيف يقلل المخاطر فعلياً، ولا يزيدها.')),
            ]),
            CaseStep(id: 'step2', type: CaseStepType.decision, title: Bi('Set Materiality', 'تحديد الأهمية النسبية'), description: Bi('You need to establish the materiality threshold for the audit.', 'تحتاج إلى تحديد عتبة الأهمية النسبية للتدقيق.'), context: Bi('Common materiality benchmarks: 0.5-2% of total expenditure, 1-3% of revenue, or 5% of profit before tax. The company has AED 500M expenditure and AED 20M profit.', 'معايير الأهمية النسبية الشائعة: 0.5-2% من إجمالي النفقات، 1-3% من الإيرادات، أو 5% من الربح قبل الضريبة. الشركة لديها 500 مليون درهم نفقات و20 مليون درهم ربح.'), question: Bi('What is the most appropriate planning materiality for this audit?', 'ما هي الأهمية النسبية الأكثر ملاءمة لتخطيط هذا التدقيق؟'), options: [
                CaseOption(Bi('AED 1M (5% of profit)', '1 مليون درهم (5% من الربح)'), feedback: Bi('Profit is a weak base here: at AED 20M it is small and volatile relative to the entity\'s AED 500M activity, so expenditure is the more stable focus.', 'الربح قاعدة ضعيفة هنا: عند 20 مليون درهم يكون صغيراً ومتقلباً مقارنة بنشاط المنشأة البالغ 500 مليون درهم، لذا النفقات هي الأساس الأكثر استقراراً.')),
                CaseOption(Bi('AED 5M (1% of expenditure)', '5 مليون درهم (1% من النفقات)'), isCorrect: true, feedback: Bi('Correct! 1% of expenditure is a commonly used benchmark that balances audit efficiency with thoroughness.', 'صحيح! 1% من النفقات هو معيار شائع الاستخدام يوازن بين كفاءة التدقيق والشمولية.')),
                CaseOption(Bi('AED 10M (2% of expenditure)', '10 مليون درهم (2% من النفقات)'), feedback: Bi('Given the new ERP system risk, using a higher materiality would reduce audit coverage when more testing is needed.', 'بالنظر إلى مخاطر نظام ERP الجديد، استخدام أهمية نسبية أعلى سيقلل تغطية التدقيق عندما نحتاج مزيداً من الاختبارات.')),
            ]),
            CaseStep(id: 'step3', type: CaseStepType.decision, title: Bi('Allocate Resources', 'تخصيص الموارد'), description: Bi('Based on risk assessment, you need to decide resource allocation.', 'بناءً على تقييم المخاطر، تحتاج إلى تحديد تخصيص الموارد.'), data: [CaseDatum(Bi('Total Budget Hours', 'إجمالي ساعات الميزانية'), '800 hours'), CaseDatum(Bi('Available Staff', 'الموظفون المتاحون'), '4 auditors'), CaseDatum(Bi('High Risk Areas', 'المجالات عالية المخاطر'), 'Payroll, Fixed Assets, IT')], question: Bi('How should you allocate the additional effort due to IT system risk?', 'كيف يجب تخصيص الجهد الإضافي بسبب مخاطر نظام تكنولوجيا المعلومات؟'), options: [
                CaseOption(Bi('Increase substantive testing of all account balances', 'زيادة الاختبارات الجوهرية لجميع أرصدة الحسابات'), feedback: Bi('Testing all accounts equally does not address the specific IT-related risks.', 'اختبار جميع الحسابات بالتساوي لا يعالج مخاطر تكنولوجيا المعلومات المحددة.')),
                CaseOption(Bi('Add IT audit specialist and focus on data migration testing', 'إضافة متخصص تدقيق تكنولوجيا المعلومات والتركيز على اختبار نقل البيانات'), isCorrect: true, feedback: Bi('Correct! IT risks require IT expertise. Testing data migration and system controls directly addresses the identified risk.', 'صحيح! مخاطر تكنولوجيا المعلومات تتطلب خبرة تكنولوجيا المعلومات. اختبار نقل البيانات وضوابط النظام يعالج المخاطر المحددة مباشرة.')),
                CaseOption(Bi('Request more time from management', 'طلب مزيد من الوقت من الإدارة'), feedback: Bi('More time may be needed, but the question is about resource allocation strategy, not timeline.', 'قد يكون هناك حاجة لمزيد من الوقت، لكن السؤال عن استراتيجية تخصيص الموارد، وليس الجدول الزمني.')),
            ]),
